import json,pathlib as P,hashlib,csv,subprocess,importlib.util
O=P.Path(__file__).resolve().parent
spec=importlib.util.spec_from_file_location('execution',O/'execute.py');x=importlib.util.module_from_spec(spec);spec.loader.exec_module(x);r=x.r
save=r.save
rows=r.read(O/'actual-schedule.json');repairs=[d for d in rows if d['phase']=='repair'];keys=['input_tokens','cached_input_tokens','cache_write_input_tokens','output_tokens','reasoning_output_tokens']
def cost(ds):return {'sessions':len(ds),'requests':sum(d.get('native',{}).get('started',0) for d in ds),'tools':sum(d.get('native',{}).get('tool_attempts',0) for d in ds),'shell_commands':sum(d.get('tools',0) for d in ds),'seconds':sum(d.get('seconds',0) for d in ds),'usage':{k:sum(d.get('usage',{}).get(k,0) for d in ds) for k in keys},'usage_incomplete':any(d.get('usage_incomplete') for d in ds)}
groups={g:{'attempted':len(ds),'valid':sum(d['status']=='VALID' for d in ds),'pass':sum(d.get('raw_verdict')=='PASS' for d in ds),'cost':cost(ds)} for g in ['A','B'] for ds in [[d for d in repairs if d['condition']==g]]}
