for rep in range(1,4):
 a=next((d for d in repairs if d['repeat']==rep and d['condition']=='A'),None);b=next((d for d in repairs if d['repeat']==rep and d['condition']=='B'),None)
 if not a or not b:continue
 ac=cost([a]);bc=cost([b]);pairs.append({'repeat':rep,'A':a['raw_verdict'],'B':b['raw_verdict'],'B_minus_A':{'requests':bc['requests']-ac['requests'],'tools':bc['tools']-ac['tools'],'seconds':bc['seconds']-ac['seconds'],'usage':{k:bc['usage'][k]-ac['usage'][k] for k in keys}}})
mechanism=[];score_rows=[]
for d in repairs:
 p=O/'runs'/d['slot'];events=[]
 for n,l in enumerate((p/'events.jsonl').read_text().splitlines(),1):
  e=json.loads(l);i=e.get('item',{})
  if e['type']=='item.completed' and i.get('type')=='command_execution':
   events.append({'event_line':n,'command':i.get('command'),'exit_code':i.get('exit_code'),'output':i.get('aggregated_output')})
 save(p/'command-evidence.json',events)
 score=r.read(p/'score.stdout.json')
 score_rows.append({'slot':d['slot'],'condition':d['condition'],'repeat':d['repeat'],'verdict':score['verdict'],'effects':score['observed_effects'],'waiting_state':score['schedules']['downloadPending']['afterFirstPending'],'ready_state':score['schedules']['downloadPending']['final']})
 source=P.Path(d['case']+'unused')
 original=O/'materials'/d['case']/'candidate';patched=p/'workspace'
 changes={str(f.relative_to(original)):{'before':r.sha(f),'after':r.sha(patched/f.relative_to(original)) if (patched/f.relative_to(original)).exists() else None} for f in original.rglob('*') if f.is_file() and (not (patched/f.relative_to(original)).exists() or r.sha(f)!=r.sha(patched/f.relative_to(original)))}
 added=[str(f.relative_to(patched)) for f in patched.rglob('*') if f.is_file() and not (original/f.relative_to(patched)).exists()]
 save(p/'patch-scope.json',{'source_changes':changes,'added_files':added,'administrative_byproducts':'__pycache__/read_policy.cpython-38.pyc generated by guard in writable candidate; raw diff retained; not a product code edit'})
 mechanism.append({'slot':d['slot'],'commands':'runs/'+d['slot']+'/command-evidence.json','source_changes':changes,'tool_nonzero_commands':[e['event_line'] for e in events if e['exit_code']!=0]})
