conf=r.read(O/'frozen-config.json');global_after=r.backend.global_snapshot();assert not changed;assert global_after==conf['global_config_before']
assert all(d.get('infrastructure_valid') and (d['phase']=='extract' or d.get('scoring_valid')) for d in rows)
assert not list(x.A.rglob('auth.json'))
save(O/'protection-check.json',{'previous_files_verified':len(protected),'changed':changed,'global_config_after':global_after,'global_config_unchanged':True,'auth_in_archive':False,'git_status':subprocess.check_output(['git','status','--short'],cwd=x.A.parents[1],text=True),'no_commit_created':True})
save(O/'score-comparison.json',score_rows);save(O/'mechanism-index.json',mechanism)
summary={'case':r.cases()[0]['case'],'scope':'U2 explicit same-source development variant, not independent generalization','planned_maintenance':6,'attempted_maintenance':len(repairs),'valid_maintenance':sum(d['status']=='VALID' for d in repairs),'unstarted':[s for s in r.read(O/'schedule.json')['slots'] if s['slot'] not in {d['slot'] for d in rows}],'groups':groups,'pairs':pairs,'extraction_cost':cost([d for d in rows if d['phase']=='extract']),'total_cost':cost(rows),'budget':{'top_level':7,'requests':156,'maintenance_per_session':24,'extraction_per_session':12,'seconds_per_session':600},'scoring_uncovered':r.read(O/'admission.json')['score_uncovered'],'no_extra_model_sessions':True,'no_retries_or_replacements':True,'currency_cost':None,'currency_reason':'No verified rate; input/output reported separately, cached tokens are subset of input; reasoning subset must not be added again. Main chat preparation/analysis tokens unavailable and excluded.'}
save(O/'summary.json',summary)
with (O/'paired-comparisons.csv').open('w') as f:
 w=csv.writer(f);w.writerow(['repeat','A','B','B-A requests','B-A tools','B-A seconds','B-A input','B-A output'])
 for p in pairs:
  z=p['B_minus_A'];w.writerow([p['repeat'],p['A'],p['B'],z['requests'],z['tools'],z['seconds'],z['usage']['input_tokens'],z['usage']['output_tokens']])
x.archive();print(json.dumps(summary,ensure_ascii=False,indent=2))
